import{_ as e,o as a,c as n,a as l}from"./app.c1132791.js";const m=JSON.parse('{"title":"Writing","description":"","frontmatter":{},"headers":[{"level":2,"title":"Resource Directory","slug":"resource-directory","link":"#resource-directory","children":[]},{"level":2,"title":"Article Directory","slug":"article-directory","link":"#article-directory","children":[]},{"level":2,"title":"Article Metadata","slug":"article-metadata","link":"#article-metadata","children":[]},{"level":2,"title":"Writing Format","slug":"writing-format","link":"#writing-format","children":[]},{"level":2,"title":"Inserting Media","slug":"inserting-media","link":"#inserting-media","children":[]},{"level":2,"title":"Svelte Components","slug":"svelte-components","link":"#svelte-components","children":[]}],"relativePath":"getting-started/writing.md"}'),r={name:"getting-started/writing.md"};function t(p,s,o,i,c,d){return a(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-hidden="true">#</a></h1><h2 id="resource-directory" tabindex="-1">Resource Directory <a class="header-anchor" href="#resource-directory" aria-hidden="true">#</a></h2><p>This project uses <code>/urara/</code> as the resource and article directory, and the initial structure looks like this:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" tabindex="0"><code><span class="line"><span style="color:#babed8;">.</span></span>
<span class="line"><span style="color:#babed8;">├── assets</span></span>
<span class="line"><span style="color:#babed8;">│   ├── any@180.png</span></span>
<span class="line"><span style="color:#babed8;">│   ├── any@192.png</span></span>
<span class="line"><span style="color:#babed8;">│   ├── any@512.png</span></span>
<span class="line"><span style="color:#babed8;">│   ├── maskable@192.png</span></span>
<span class="line"><span style="color:#babed8;">│   └── maskable@512.png</span></span>
<span class="line"><span style="color:#babed8;">├── favicon.png</span></span>
<span class="line"><span style="color:#babed8;">└── hello-world</span></span>
<span class="line"><span style="color:#babed8;">    ├── elements</span></span>
<span class="line"><span style="color:#babed8;">    │   └── +page.svelte.md</span></span>
<span class="line"><span style="color:#babed8;">    ├── toc-disabled</span></span>
<span class="line"><span style="color:#babed8;">    │   └── +page.md</span></span>
<span class="line"><span style="color:#babed8;">    ├── urara.webp</span></span>
<span class="line"><span style="color:#babed8;">    └── +page.svelte.md</span></span>
<span class="line"><span style="color:#babed8;"></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>Urara only processes Markdown files with the suffix <code>.md</code>, and does not process other files.</p><blockquote><p>There is no difference between the <code>+page.svelte.md</code> and <code>+page.md</code> nomenclature, which is used only to mark whether the Svelte component is used.</p></blockquote><h2 id="article-directory" tabindex="-1">Article Directory <a class="header-anchor" href="#article-directory" aria-hidden="true">#</a></h2><p>You can create any directory under the <code>/urara/</code> directory, and the directory containing the <code>.md</code> file will be processed as an article page.</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight has-highlighted-lines" tabindex="0"><code><span class="line"><span style="color:#babed8;">.</span></span>
<span class="line"><span style="color:#babed8;">└── hello-world</span></span>
<span class="line"><span style="color:#babed8;">    ├── elements</span></span>
<span class="line highlighted"><span style="color:#babed8;">    │   └── +page.svelte.md</span></span>
<span class="line"><span style="color:#babed8;">    ├── toc-disabled</span></span>
<span class="line highlighted"><span style="color:#babed8;">    │   └── +page.md</span></span>
<span class="line"><span style="color:#babed8;">    ├── urara.webp</span></span>
<span class="line highlighted"><span style="color:#babed8;">    └── +page.svelte.md</span></span>
<span class="line"><span style="color:#babed8;"></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>The above content will generate three pages after processing:</p><ol><li><code>example.com/hello-world/</code></li><li><code>example.com/hello-world/elements/</code></li><li><code>example.com/hello-world/toc-disabled/</code></li></ol><p>You can create as many directories as you like, but note: <strong>Do not store multiple <code>.md</code> files in the same directory.</strong></p><h2 id="article-metadata" tabindex="-1">Article Metadata <a class="header-anchor" href="#article-metadata" aria-hidden="true">#</a></h2><p>When writing, you will also need to write article metadata, an example of which is shown below:</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki material-theme-palenight" tabindex="0"><code><span class="line"><span style="color:#BABED8;">---</span></span>
<span class="line"><span style="color:#F07178;">title</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Hello World</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">// title</span></span>
<span class="line"><span style="color:#F07178;">image</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">/hello-world/urara.webp</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">// title image</span></span>
<span class="line"><span style="color:#F07178;">created</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">2021-11-01 // create time</span></span>
<span class="line"><span style="color:#F07178;">updated</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">2021-12-12 // update time</span></span>
<span class="line"><span style="color:#F07178;">published</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">2021-11-04 // publish time</span></span>
<span class="line"><span style="color:#F07178;">tags</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">// label</span></span>
<span class="line"><span style="color:#BABED8;">  </span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Hello World</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#BABED8;">  </span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Urara</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#F07178;">flags</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">// custom flags</span></span>
<span class="line"><span style="color:#BABED8;">  </span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">unlisted // hide article on the home page</span></span>
<span class="line"><span style="color:#BABED8;">---</span></span>
<span class="line"></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>This project is compatible with the <a href="https://fff.js.org/" target="_blank" rel="noreferrer"><strong>FFF Flavored Frontmatter</strong></a> specification, but not all variables can be used.</p><h2 id="writing-format" tabindex="-1">Writing Format <a class="header-anchor" href="#writing-format" aria-hidden="true">#</a></h2><p>You can write articles using Markdown syntax, which is a lightweight markup language.</p><p>If you have never heard of Markdown, you can learn the basic syntax at <a href="https://www.markdownguide.org/basic-syntax/" target="_blank" rel="noreferrer"><strong>Basic Syntax | Markdown Guide</strong></a>.</p><p>This project is also compatible with some of Markdown&#39;s extended syntax: <a href="https://www.markdownguide.org/extended-syntax/" target="_blank" rel="noreferrer"><strong>Extended Syntax | Markdown Guide</strong></a>, and the following extended syntax is not available at this time.</p><ul><li><a href="https://www.markdownguide.org/extended-syntax/#heading-ids" target="_blank" rel="noreferrer"><strong>Heading IDs</strong></a></li><li><a href="https://www.markdownguide.org/extended-syntax/#definition-lists" target="_blank" rel="noreferrer"><strong>Definition Lists</strong></a></li><li><a href="https://www.markdownguide.org/extended-syntax/#using-emoji-shortcodes" target="_blank" rel="noreferrer"><strong>Using Emoji Shortcodes</strong></a></li><li><a href="https://www.markdownguide.org/extended-syntax/#highlight" target="_blank" rel="noreferrer"><strong>Highlight</strong></a></li><li><a href="https://www.markdownguide.org/extended-syntax/#subscript" target="_blank" rel="noreferrer"><strong>Subscript</strong></a></li><li><a href="https://www.markdownguide.org/extended-syntax/#superscript" target="_blank" rel="noreferrer"><strong>Superscript</strong></a></li><li><a href="https://www.markdownguide.org/extended-syntax/#disabling-automatic-url-linking" target="_blank" rel="noreferrer"><strong>Disabling Automatic URL Linking</strong></a></li></ul><h2 id="inserting-media" tabindex="-1">Inserting Media <a class="header-anchor" href="#inserting-media" aria-hidden="true">#</a></h2><p>You can insert media content into your article via Markdown syntax or HTML code.</p><p>When inserting media, pay attention to the directory where the media is stored, for example, to insert <code>urara.webp</code> in the following <code>hello-world</code> article:</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight has-highlighted-lines" tabindex="0"><code><span class="line"><span style="color:#babed8;">.</span></span>
<span class="line"><span style="color:#babed8;">├── src</span></span>
<span class="line"><span style="color:#babed8;">└── urara</span></span>
<span class="line"><span style="color:#babed8;">    └── hello-world</span></span>
<span class="line highlighted"><span style="color:#babed8;">        ├── urara.webp</span></span>
<span class="line"><span style="color:#babed8;">        └── +page.svelte.md</span></span>
<span class="line"><span style="color:#babed8;"></span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>When filling in the path, calculate the file path starting from the <code>urara</code> directory in the project:</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki material-theme-palenight" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">![</span><span style="color:#C3E88D;">image description</span><span style="color:#89DDFF;">](</span><span style="color:#BABED8;text-decoration:underline;">/hello-world/urara.webp</span><span style="color:#89DDFF;">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="svelte-components" tabindex="-1">Svelte Components <a class="header-anchor" href="#svelte-components" aria-hidden="true">#</a></h2><p>You can use Svelte components in your articles by simply importing them before use:</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki material-theme-palenight" tabindex="0"><code><span class="line"><span style="color:#BABED8;">&lt;script&gt;</span></span>
<span class="line"><span style="color:#BABED8;">  import Component from &#39;$lib/components/extra/component.svelte&#39;</span></span>
<span class="line"><span style="color:#BABED8;">&lt;/script&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Fill in the information according to the needs of the component at the time of use:</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki material-theme-palenight" tabindex="0"><code><span class="line"><span style="color:#BABED8;">&lt;Component attribute=&quot;info&quot;/&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This document also organizes the Svelte components that can be used in Urara: <a href="http://urara-docs.netlify.app/advanced/extension.html#article-component" target="_blank" rel="noreferrer"><strong>Article Components</strong></a>.</p>`,33)])])}const h=e(r,[["render",t]]);export{m as __pageData,h as default};
